"""A shelf of books, kept in the order they were added."""
from __future__ import annotations

from dataclasses import dataclass


@dataclass
class Book:
    title: str
    author: str
    read: bool = False


class Shelf:
    def __init__(self) -> None:
        self._books: list[Book] = []

    def add(self, title: str, author: str) -> Book:
        """Add a book; a title already on the shelf is refused."""
        if any(b.title == title for b in self._books):
            raise ValueError(f"already on the shelf: {title}")
        book = Book(title, author)
        self._books.append(book)
        return book

    def books(self) -> list[Book]:
        """Every book, in the order it was added."""
        return list(self._books)
